def make_data(n_ep: int, n_ch: int, n_t: int):
    X = np.zeros((n_ep, n_ch, n_t))
    for e in range(n_ep):
        for c in range(n_ch):
            for t in range(n_t):
                v = (e * 1009 + c * 7919 + t * 104729 + e * c * t * 13 + t * t * (c + 1) * 3) % 101
                X[e, c, t] = ((v - 50.0) / 25.0 + np.sin(0.3 * t + 0.1 * c)) * 1e-5
    X[3] *= 8.0
    X[11, :20] *= 6.0
    X[17, 4] *= 12.0
    X[17, 9] *= 10.0
    X[25, 2:6] *= 9.0
    X[30, 13] += 3e-4
    X[34, 0:3] *= 7.0
    return X

def make_epochs(X):
    info = mne.create_info(NAMES, 100., 'eeg')
    ep = mne.EpochsArray(X, info)
    ep.set_montage('standard_1020')
    return ep

def close(got, exp: List[float], rtol: float = 1e-10, atol: float = 1e-20) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    ok = True
    worst = 0.0
    for i in range(len(exp)):
        if np.isinf(exp[i]):
            if g[i] != exp[i]:
                print("mismatch at", i, g[i], exp[i])
                ok = False
            continue
        d = abs(g[i] - exp[i])
        if d > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            ok = False
        if exp[i] != 0:
            worst = max(worst, d / abs(exp[i]))
    print("  max rel err", worst)
    return ok

