@test
def test_bayesopt():
    gp = _GaussianProcess().fit(np.array([[0.1], [0.5], [1.3], [2.0]]), np.array([1.0, 0.2, 0.7, 1.5]))
    m, s = gp.predict_std(np.array([[0.3], [1.0], [1.7]]))
    assert close(m, E_gp_mean, 1e-9)
    assert close(s, E_gp_std, 1e-7)
    assert close(expected_improvement(gp, 0.2, np.array([0.3, 1.0, 1.7])), E_ei, 1e-9)
    def f(x: float) -> float:
        return (x - 0.73) ** 2
    bx, bf = bayes_opt(f, np.array([0.0, 0.5, 1.0, 2.0]), np.linspace(0, 2, 41), expected_improvement, 10)
    assert close([bx, bf], E_bo)
test_bayesopt()

@test
def test_clean_by_interp():
    ci = clean_by_interp(ep, verbose=False).get_data()
    sub = ci[np.array([0, 3, 17])][:, np.array([0, 4, 21, 31])][:, :, :5]
    assert close(sub, E_cbi, 1e-8)
test_clean_by_interp()

@test
def test_thresholds():
    th = compute_thresholds(ep, random_state=42, verbose=False)
    assert close([th[n] for n in NAMES], E_th, 1e-9)
    th2 = compute_thresholds(ep, random_state=7, augment=False, picks=list(range(10)), verbose=False)
    assert close([th2[n] for n in NAMES[:10]], E_th2, 1e-9)
    th3 = compute_thresholds(ep, method='random_search', random_state=3, picks=[0, 1, 2], verbose=False)
    assert close([th3[n] for n in NAMES[:3]], E_th3, 1e-9)
test_thresholds()

@test
def test_global():
    rj = get_rejection_threshold(ep, verbose=False)
    assert close([rj['eeg']], E_rj)
    assert len(rj) == 1
    rj2 = get_rejection_threshold(ep, decim=2, cv=3, verbose=False)
    assert close([rj2['eeg']], E_rj2)
    tr, te, pr = validation_curve(ep, param_range=None, cv=4, return_param_range=True)
    assert close(tr, E_vc_tr, 1e-9)
    assert close(te, E_vc_te, 1e-9)
    assert close(pr, E_vc_pr, 1e-12)
    g = _GlobalAutoReject(32, 60, thresh=2e-4).fit(X.reshape((40, 32 * 60)))
    assert close([g.score(X.reshape((40, 32 * 60)))], E_gar, 1e-9)
test_global()

@test
def test_autoreject():
    ar = AutoReject(n_interpolate=np.array([1, 4, 8]), consensus=np.linspace(0, 1, 6),
                    cv=4, random_state=42, verbose=False)
    ar.fit(ep)
    assert close([ar.threshes_[n] for n in NAMES], E_ar_th, 1e-9)
    assert close([ar.consensus_['eeg'], float(ar.n_interpolate_['eeg'])], E_ar_ci)
    L = ar.loss_['eeg']
    assert close(np.where(np.isinf(L), -1.0, L), E_ar_loss, 1e-8)
    clean, log = ar.transform(ep, return_log=True)
    assert close(log.bad_epochs.astype(float), E_ar_bad)
    assert close(log.labels, E_ar_labels)
    assert close([float(v) for v in clean.get_data().shape], E_ar_clean_shape)
    assert close(clean.get_data()[:, np.array([2, 4, 9, 13])][:, :, :4], E_ar_clean, 1e-8)
    assert close(ar.local_reject_['eeg'].mean_[np.array([0, 9, 31])][:, :6], E_ar_mean, 1e-8)
    ar.save("/tmp/typhon_ar_test.json", overwrite=True)
    ar2 = read_auto_reject("/tmp/typhon_ar_test.json")
    assert close(ar2.get_reject_log(ep).labels, E_ar_labels)
    assert ar2.consensus_['eeg'] == ar.consensus_['eeg']
    log.save("/tmp/typhon_ar_log.npz", overwrite=True)
    log3 = read_reject_log("/tmp/typhon_ar_log.npz")
    assert log3.ch_names == NAMES
    assert close(log3.labels, E_ar_labels)
    assert close(log3.bad_epochs.astype(float), E_ar_bad)
test_autoreject()

@test
def test_local():
    from autoreject import _AutoReject, RejectLog
    la = _AutoReject(n_interpolate=4, consensus=0.3, picks=list(range(16)), verbose=False,
                     random_state=5)
    la.fit(ep)
    llog = la.get_reject_log(ep)
